import sys, itertools, json
import numpy as np
import cirq

def trotter(rows, cols, layers, exp, cycles, seed):
    qs = cirq.GridQubit.rect(rows, cols)
    rng = np.random.default_rng(seed)
    moments = []
    for l in range(layers):
        moments.append(cirq.Moment((cirq.Y**exp)(q) for q in qs))
        used=set(); pairs=[]
        for a in qs:
            for b in qs:
                if a < b and a.is_adjacent(b) and a not in used and b not in used and rng.random()<0.6:
                    pairs.append((a,b)); used|={a,b}
        moments.append(cirq.Moment(cirq.CZ(a,b) for a,b in pairs))
    c = cirq.Circuit.from_moments(*moments) * cycles + cirq.Moment(cirq.M(*qs))
    gauge = cirq.transformers.gauge_compiling.cz_gauge.CZGaugeTransformer
    return gauge(c, prng=np.random.default_rng(seed))

def rand_1q(rng, q):
    k = rng.integers(8)
    if k == 0: return cirq.PhasedXZGate(axis_phase_exponent=rng.random(), x_exponent=rng.random(), z_exponent=rng.random())(q)
    if k == 1: return (cirq.X**rng.random())(q)
    if k == 2: return (cirq.Y**rng.random())(q)
    if k == 3: return (cirq.Z**rng.random())(q)
    if k == 4: return cirq.H(q)
    if k == 5: return [cirq.X, cirq.Y, cirq.Z, cirq.S, cirq.T][rng.integers(5)](q)
    if k == 6: return cirq.I(q)
    return cirq.MatrixGate(cirq.testing.random_unitary(2, random_state=rng.integers(1<<30)))(q)

def moments_circuit(nq, seed, phases=True, tags=False):
    rng = np.random.default_rng(seed)
    qs = cirq.LineQubit.range(nq)
    ms = []
