@transformer_api.transformer
def merge_single_qubit_moments_to_phxz(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    atol: float = 1e-8,
) -> cirq.Circuit:
    """Merges adjacent moments with only 1-qubit rotations to a single moment with PhasedXZ gates.

    Each run of adjacent mergeable moments is replaced by a single moment. On every qubit, the
    unitaries of the run's operations are multiplied and converted to one `cirq.PhasedXZGate`,
    which is dropped if it is close to identity. A `cirq.PhasedXZGate` that is the only
    operation on its qubit in the run is kept as it is. If the run contains several global
    phase operations, they are combined into a single `cirq.GlobalPhaseGate`.

    Args:
        circuit: Input circuit to transform. It will not be modified.
        context: `cirq.TransformerContext` storing common configurable options for transformers.
        atol: Absolute tolerance to angle error. Larger values allow more negligible gates to be
            dropped, smaller values increase accuracy.

    Returns:
        Copy of the transformed input circuit.
    """
    tags_to_ignore = set(context.tags_to_ignore) if context else set()
    deep = context.deep if context else False

    def can_merge_moment(m: cirq.Moment):
        return all(
            protocols.num_qubits(op) <= 1
            and protocols.has_unitary(op)
            and tags_to_ignore.isdisjoint(op.tags)
            for op in m
        )

    def merge_run(run: list[cirq.Moment]) -> cirq.Moment:
        ops_by_qubit: dict[cirq.Qid, list[cirq.Operation]] = defaultdict(list)
        phase_ops: list[cirq.Operation] = []
        for m in run:
            for op in m:
                if op.qubits:
                    ops_by_qubit[op.qubits[0]].append(op)
                else:
                    phase_ops.append(op)
        ret_ops = []
        for q, q_ops in ops_by_qubit.items():
            if len(q_ops) == 1 and isinstance(q_ops[0].gate, ops.PhasedXZGate):
                ret_ops.append(q_ops[0])
                continue
            mat = protocols.unitary(q_ops[0])
            for op in q_ops[1:]:
                mat = protocols.unitary(op) @ mat
            gate = single_qubit_decompositions.single_qubit_matrix_to_phxz(mat, atol)
            if gate:
                ret_ops.append(gate(q))
        if len(phase_ops) > 1:
            coefficient = np.prod([protocols.unitary(op)[0, 0] for op in phase_ops])
            phase_ops = [ops.GlobalPhaseGate(coefficient).on()]
        return circuits.Moment(ret_ops + phase_ops)

    def merge_moments(c: CIRCUIT_TYPE, recursion_tags_to_ignore: Sequence[Hashable]) -> CIRCUIT_TYPE:
        if deep:
            # Like `cirq.merge_moments`, only circuit operations directly in the input circuit
            # are skipped when tagged with `tags_to_ignore`.
            c = transformer_primitives.map_operations(
                c,
                lambda op, _: (
                    op.untagged.replace(circuit=merge_moments(op.untagged.circuit, ()))
                    .with_tags(*op.tags)
                    if isinstance(op.untagged, circuits.CircuitOperation)
                    else op
                ),
                tags_to_ignore=recursion_tags_to_ignore,
            )
        merged_moments: list[cirq.Moment] = []
        run: list[cirq.Moment] = []
        for moment in [*c, None]:
            if moment is not None and can_merge_moment(moment):
                run.append(moment)
                continue
            if run:
                merged_moments.append(run[0] if len(run) == 1 else merge_run(run))
                run = []
            if moment is not None:
                merged_moments.append(moment)
        if isinstance(c, circuits.FrozenCircuit):
            return cast(CIRCUIT_TYPE, circuits.FrozenCircuit(merged_moments, tags=c.tags))
        return cast(CIRCUIT_TYPE, circuits.Circuit(merged_moments))

    return merge_moments(circuit, tuple(tags_to_ignore)).unfreeze(copy=False)


def _sweep_on_symbols(sweep: Sweep, symbols: set[sympy.Symbol]) -> Sweep:
    new_resolvers: list[cirq.ParamResolver] = []
    for resolver in sweep:
        param_dict: cirq.ParamMappingType = {s: resolver.value_of(s) for s in symbols}
        new_resolvers.append(ParamResolver(param_dict))
